import { FbField, FbSchema, FbFieldType, fbId, fbKeyFrom } from './_form-schema';
import { FbLang } from './_fb-i18n';

/** ───────────────────────────── FORM BUILDER — TRỢ LÝ AI ─────────────────────────────
 *  Sinh form từ MÔ TẢ tiếng Việt/Anh (tham khảo Vueform AI Assistant).
 *  Demo OFFLINE — heuristic thuần (template nghiệp vụ HRM + trích xuất field theo từ khoá),
 *  KHÔNG gọi API LLM; production chỉ cần thay hàm này bằng lời gọi model, schema giữ nguyên. */

/** Bỏ dấu tiếng Việt + lowercase để so khớp từ khoá. */
function norm(s: string): string {
  return s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'd').toLowerCase();
}

let aiSeq = 0;
function f(partial: Partial<FbField> & { type: FbFieldType; key: string; label: string }): FbField {
  return { id: fbId('f'), span: 'half', ...partial };
}

/** Đoán LOẠI field từ cụm mô tả (từ khoá → type). */
function guessType(phrase: string): FbFieldType {
  const p = norm(phrase);
  if (/(email|thu dien tu)/.test(p)) return 'email';
  if (/(dien thoai|sdt|phone)/.test(p)) return 'phone';
  if (/(ngay|date|sinh nhat|han)/.test(p)) return 'date';
  if (/(gio|time)/.test(p)) return 'time';
  if (/(luong|tien|thu nhap|chi phi|salary|money|budget)/.test(p)) return 'money';
  if (/(phan tram|%|percent|trong so)/.test(p)) return 'percent';
  if (/(mo ta|ghi chu|noi dung|ly do|note|description|comment)/.test(p)) return 'textarea';
  if (/(so luong|so nam|so thang|so ngay|number|tuoi)/.test(p)) return 'number';
  if (/(dinh kem|tep|file|upload|cv|ho so)/.test(p)) return 'upload';
  if (/(hinh|anh|image|photo)/.test(p)) return 'image';
  if (/(danh gia|rating|sao)/.test(p)) return 'rating';
  if (/(dia chi|address)/.test(p)) return 'address';
  if (/(nhan vien|nguoi phu trach|quan ly|employee|manager)/.test(p)) return 'user';
  if (/(ma so|ma tu sinh|ma\b|code)/.test(p)) return 'autocode';
  if (/(dong y|xac nhan|checkbox|check)/.test(p)) return 'checkbox';
  if (/(bat|tat|toggle|kich hoat)/.test(p)) return 'toggle';
  if (/(chon nhieu|multi)/.test(p)) return 'multiselect';
  if (/(phong ban|chuc vu|loai|trang thai|nhom|select|danh sach|don vi|hinh thuc)/.test(p)) return 'select';
  return 'text';
}

/** Viết hoa chữ đầu. */
function cap(s: string): string { return s ? s[0].toUpperCase() + s.slice(1) : s; }

/** ─── TEMPLATE nghiệp vụ HRM dựng sẵn (match theo chủ đề) ─── */
