/** Trích danh sách field từ mệnh đề "gồm/bao gồm/có các trường: a, b và c". */
function extractFields(prompt: string): FbField[] {
  const m = /(?:gồm|bao gồm|có|với|:)([^.。]*)$/i.exec(prompt) || [null, prompt];
  const tail = (m[1] || prompt);
  const parts = tail.split(/,|;|\bvà\b|\band\b/i).map((x) => x.trim()).filter((x) => x.length > 1 && x.length < 60);
  const out: FbField[] = [];
  const seen = new Set<string>();
  for (const raw of parts.slice(0, 14)) {
    const required = /bắt buộc|\*|required/i.test(raw);
    const label = cap(raw.replace(/bắt buộc|\(|\)|\*|required/gi, '').trim());
    if (!label) continue;
    let key = fbKeyFrom(label);
    while (seen.has(key)) key += String(++aiSeq);
    seen.add(key);
    const type = guessType(label);
    out.push(f({
      type, key, label, required: required || undefined,
      span: type === 'textarea' || type === 'upload' || type === 'address' ? 'full' : 'half',
      options: type === 'select' || type === 'multiselect' || type === 'radio' ? ['Lựa chọn 1', 'Lựa chọn 2', 'Lựa chọn 3'] : undefined,
    }));
  }
  return out;
}

/** Sinh schema từ mô tả. null = không hiểu (prompt trống/quá ngắn). */
export function fbAiGenerate(prompt: string, _lang: FbLang): FbSchema | null {
  const p = prompt.trim();
  if (p.length < 4) return null;
  const n = norm(p);
  // ── template nghiệp vụ khớp chủ đề ──
  if (/(nghi phep|xin nghi|don nghi|leave)/.test(n)) return tplLeave();
  if (/(ung vien|tuyen dung|candidate|recruit)/.test(n)) return tplCandidate();
  if (/(hop dong|contract)/.test(n)) return tplContract();
  if (/(khao sat|danh gia|survey|feedback)/.test(n)) return tplSurvey();
  // ── generic: trích field từ mô tả ──
  const fields = extractFields(p);
  if (!fields.length) return null;
  // Tên form = mệnh đề đầu trước "gồm/có/với"
  const nameM = /^(.*?)(?:\s+(?:gồm|bao gồm|có|với)\b|:|$)/i.exec(p);
  const name = cap((nameM?.[1] || 'Biểu mẫu mới').trim()).slice(0, 60) || 'Biểu mẫu mới';
  return {
    version: 2, name, desc: 'Form sinh bởi Trợ lý AI.',
    sections: [{ id: fbId('sec'), title: 'Thông tin chung', fields }],
    rules: [],
  };
}

