  protected readonly paramKindOpts = computed<HrmOption[]>(() => (this.fbLang() === 'vi'
    ? [{ value: 'field', label: 'Trường trên form' }, { value: 'const', label: 'Giá trị cố định' }]
    : [{ value: 'field', label: 'Form field' }, { value: 'const', label: 'Fixed value' }]));
  private readonly _pmCache = new Map<string, { kind: 'field' | 'const'; val: string }>();
  protected paramOf(f: FbField, pn: string): { kind: 'field' | 'const'; val: string } {
    const cur = f.dsMeta?.paramMap?.[pn];
    if (cur) return cur;
    const k = f.id + ':' + pn;
    let d = this._pmCache.get(k);
    if (!d) { d = { kind: 'field', val: '' }; this._pmCache.set(k, d); }
    return d;
  }
  protected patchParam(f: FbField, pn: string, patch: Partial<{ kind: 'field' | 'const'; val: string }>): void {
    const cur = this.paramOf(f, pn);
    this.patchField(f.id, { dsMeta: { ...(f.dsMeta || {}), paramMap: { ...(f.dsMeta?.paramMap || {}), [pn]: { ...cur, ...patch } } } });
  }
