/** ───────────────────────────── FORM BUILDER — FORMULA ENGINE ─────────────────────────────
 *  Bộ đánh giá công thức AN TOÀN cho action "compute" của Form Builder (no-code).
 *  KHÔNG dùng eval/Function — tokenizer + parser đệ quy (recursive descent) viết tay.
 *
 *  Ngôn ngữ:
 *  - Tham chiếu field:  [key bất kỳ]  — key lấy nguyên văn tới ']' (trim), resolve qua get(key).
 *  - Literal:           số (int/decimal), chuỗi trong nháy đơn HOẶC nháy kép.
 *  - Toán tử (ưu tiên thấp→cao):  ||  ·  &&  ·  == !=  ·  < <= > >=  ·  + -  ·  * / %  ·  - (unary)  ·  ( )
 *  - Hàm (không phân biệt hoa/thường):
 *      IF(cond, a, b) · TODAY() · ADDDAY(date, n) · ADDMONTH(date, n) · ADDYEAR(date, n)
 *    date là chuỗi 'dd/MM/yyyy' (hoặc Date từ get()); kết quả trả về chuỗi 'dd/MM/yyyy'.
 *    ADDMONTH/ADDYEAR kẹp ngày cuối tháng (31/01 + 1 tháng → 28/02 hoặc 29/02).
 *  - So sánh: cả 2 vế là ngày dd/MM/yyyy → so timestamp; cả 2 vế là số → so số; còn lại so chuỗi.
 *  - '+': cả 2 vế là số → cộng số; ngược lại → nối chuỗi.
 *  - Truthiness (IF/&&/||): false, 0, '', null → false; còn lại → true.
 *  - MỌI lỗi (cú pháp, ngày sai, hàm lạ…) → trả '' — KHÔNG BAO GIỜ throw ra ngoài. */

/** Giá trị kết quả của công thức. */
export type FbExprValue = string | number | boolean;

/** Đánh giá trì hoãn — cho phép IF chỉ chạy nhánh được chọn, &&/|| short-circuit thật
 *  (lỗi trong nhánh KHÔNG được chọn không được làm hỏng cả công thức). */
type FbThunk = () => FbExprValue;

/** 1 token sau khi tách. */
interface FbTok {
  t: 'num' | 'str' | 'field' | 'ident' | 'op';
  v: string;
}

/** Số ngày của tháng (m: 1-12). */
function fbDaysInMonth(y: number, m: number): number {
  return new Date(y, m, 0).getDate();
}

/** Parse 'dd/MM/yyyy' (hoặc Date) → Date; sai định dạng/ngày không tồn tại → null. */
function fbParseDmy(v: FbExprValue | Date): Date | null {
  if (v instanceof Date) { return Number.isNaN(v.getTime()) ? null : v; }
  if (typeof v !== 'string') { return null; }
  const m = /^\s*(\d{1,2})\/(\d{1,2})\/(\d{4})\s*$/.exec(v);
  if (!m) { return null; }
  const d = +m[1], mo = +m[2], y = +m[3];
  if (mo < 1 || mo > 12 || d < 1 || d > fbDaysInMonth(y, mo)) { return null; }
  return new Date(y, mo - 1, d);
}

/** Format Date → 'dd/MM/yyyy'. */
function fbFmtDmy(d: Date): string {
  const p2 = (n: number) => String(n).padStart(2, '0');
  return `${p2(d.getDate())}/${p2(d.getMonth() + 1)}/${d.getFullYear()}`;
}

/** Cộng n tháng, KẸP ngày cuối tháng (31/01 +1 → 28/02 hoặc 29/02). */
function fbAddMonths(d: Date, n: number): Date {
  const total = d.getMonth() + n;
  const y = d.getFullYear() + Math.floor(total / 12);
  const m = ((total % 12) + 12) % 12;
  return new Date(y, m, Math.min(d.getDate(), fbDaysInMonth(y, m + 1)));
}

/** Giá trị có coi là SỐ không (Number() ra NaN hoặc chuỗi rỗng → không). */
function fbIsNum(v: FbExprValue): boolean {
  if (typeof v === 'number') { return true; }
  if (typeof v !== 'string' || v.trim() === '') { return false; }
  return !Number.isNaN(Number(v));
}

/** Ép về số; không ép được → NaN. */
function fbToNum(v: FbExprValue): number {
  if (typeof v === 'number') { return v; }
  return fbIsNum(v) ? Number(v) : NaN;
}

/** Truthiness của Form Builder: false, 0, '', null → false. */
function fbTruthy(v: FbExprValue): boolean {
  return v !== false && v !== 0 && v !== '' && v != null;
}

/** So sánh 2 giá trị: ngày → timestamp · số → số · còn lại → chuỗi. Trả <0 · 0 · >0. */
function fbCompare(a: FbExprValue, b: FbExprValue): number {
  const da = fbParseDmy(a), db = fbParseDmy(b);
  if (da && db) { return da.getTime() - db.getTime(); }
  if (fbIsNum(a) && fbIsNum(b)) { return fbToNum(a) - fbToNum(b); }
  const sa = String(a), sb = String(b);
  return sa < sb ? -1 : sa > sb ? 1 : 0;
}

/** Chuẩn hoá giá trị field từ get(): null/undefined → '' · Date → 'dd/MM/yyyy'. */
function fbNormField(v: unknown): FbExprValue {
  if (v == null) { return ''; }
  if (v instanceof Date) { return fbFmtDmy(v); }
  if (typeof v === 'number' || typeof v === 'boolean' || typeof v === 'string') { return v; }
  return String(v);
}

/** Ép về Date từ 'dd/MM/yyyy'; sai → throw (fbEvalFormula sẽ nuốt thành ''). */
function fbToDate(v: FbExprValue): Date {
  const d = fbParseDmy(v);
  if (!d) { throw new Error(`ngày không hợp lệ: ${String(v)}`); }
  return d;
}

/** Ép về số nguyên (tham số n của ADDDAY/ADDMONTH/ADDYEAR); NaN → throw. */
function fbToInt(v: FbExprValue): number {
  const n = fbToNum(v);
  if (Number.isNaN(n)) { throw new Error(`không phải số: ${String(v)}`); }
  return Math.trunc(n);
}

/** Gọi hàm built-in (tên KHÔNG phân biệt hoa/thường); hàm lạ/sai số tham số → throw.
 *  Nhận THUNK — IF chỉ force nhánh được chọn (nhánh còn lại có lỗi cũng không ảnh hưởng);
 *  hàm khác cần đủ giá trị nên force toàn bộ tham số trước khi tính. */
function fbCallFn(name: string, args: FbThunk[]): FbExprValue {
  const need = (n: number) => {
    if (args.length !== n) { throw new Error(`${name} cần ${n} tham số`); }
  };
  switch (name.toUpperCase()) {
    case 'IF':
      need(3);
      return fbTruthy(args[0]()) ? args[1]() : args[2]();
    case 'TODAY':
      need(0);
      return fbFmtDmy(new Date());
    case 'ADDDAY': {
      need(2);
      const d = fbToDate(args[0]());
      return fbFmtDmy(new Date(d.getFullYear(), d.getMonth(), d.getDate() + fbToInt(args[1]())));
    }
    case 'ADDMONTH':
      need(2);
      return fbFmtDmy(fbAddMonths(fbToDate(args[0]()), fbToInt(args[1]())));
    case 'ADDYEAR':
      need(2);
      return fbFmtDmy(fbAddMonths(fbToDate(args[0]()), fbToInt(args[1]()) * 12));
    default:
      throw new Error(`hàm không hỗ trợ: ${name}`);
  }
}

/** Tách chuỗi công thức thành token; ký tự lạ / chuỗi & [ không đóng → throw. */
function fbTokenize(src: string): FbTok[] {
  const toks: FbTok[] = [];
  let i = 0;
  while (i < src.length) {
    const c = src[i];
    if (/\s/.test(c)) { i++; continue; }
    // ── Tham chiếu field: [bất kỳ tới ']'] — hỗ trợ key tiếng Việt có dấu/khoảng trắng
    if (c === '[') {
      const end = src.indexOf(']', i + 1);
      if (end < 0) { throw new Error('thiếu ]'); }
      toks.push({ t: 'field', v: src.slice(i + 1, end).trim() });
      i = end + 1; continue;
    }
    // ── Chuỗi: nháy đơn HOẶC nháy kép
    if (c === "'" || c === '"') {
      const end = src.indexOf(c, i + 1);
      if (end < 0) { throw new Error('thiếu đóng nháy'); }
      toks.push({ t: 'str', v: src.slice(i + 1, end) });
      i = end + 1; continue;
    }
    // ── Số: int/decimal
    if (/\d/.test(c)) {
      const m = /^\d+(\.\d+)?/.exec(src.slice(i))!;
      toks.push({ t: 'num', v: m[0] });
      i += m[0].length; continue;
    }
    // ── Tên hàm
    if (/[A-Za-z_]/.test(c)) {
      const m = /^[A-Za-z_][A-Za-z0-9_]*/.exec(src.slice(i))!;
      toks.push({ t: 'ident', v: m[0] });
      i += m[0].length; continue;
    }
    // ── Toán tử 2 ký tự trước, 1 ký tự sau ('=' đơn coi như '==' — dễ tính cho no-code)
    const two = src.slice(i, i + 2);
    if (['||', '&&', '==', '!=', '<=', '>='].includes(two)) {
      toks.push({ t: 'op', v: two });
      i += 2; continue;
    }
    if ('<>+-*/%(),'.includes(c)) {
      toks.push({ t: 'op', v: c });
      i++; continue;
    }
    if (c === '=') { toks.push({ t: 'op', v: '==' }); i++; continue; }
    throw new Error(`ký tự lạ: ${c}`);
  }
  return toks;
}

/** Đánh giá công thức Form Builder. Mọi lỗi → trả '' (không bao giờ throw). */
export function fbEvalFormula(formula: string, get: (key: string) => unknown): FbExprValue {
  try {
    const toks = fbTokenize(formula);
    let pos = 0;

    const peek = (): FbTok | undefined => toks[pos];
    const isOp = (...ops: string[]): boolean => {
      const t = peek();
      return !!t && t.t === 'op' && ops.includes(t.v);
    };
    const expectOp = (op: string): void => {
      if (!isOp(op)) { throw new Error(`cần '${op}'`); }
      pos++;
    };

    // ── Phần tử: số · chuỗi · [field] · hàm(...) · (biểu thức) — TRẢ THUNK, chưa tính.
    const parsePrimary = (): FbThunk => {
      const t = peek();
      if (!t) { throw new Error('hết token'); }
      if (t.t === 'num') { pos++; const v = Number(t.v); return () => v; }
      if (t.t === 'str') { pos++; const v = t.v; return () => v; }
      if (t.t === 'field') { pos++; const key = t.v; return () => fbNormField(get(key)); }
      if (t.t === 'ident') {
        pos++;
        const name = t.v;
        expectOp('(');
        const args: FbThunk[] = [];
        if (!isOp(')')) {
          args.push(parseOr());
          while (isOp(',')) { pos++; args.push(parseOr()); }
        }
        expectOp(')');
        return () => fbCallFn(name, args);
      }
      if (isOp('(')) {
        pos++;
        const v = parseOr();
        expectOp(')');
        return v;
      }
      throw new Error(`token lạ: ${t.v}`);
    };

    // ── Unary minus
    const parseUnary = (): FbThunk => {
      if (isOp('-')) {
        pos++;
        const inner = parseUnary();
        return () => {
          const n = fbToNum(inner());
          if (Number.isNaN(n)) { throw new Error('unary - cần số'); }
          return -n;
        };
      }
      return parsePrimary();
    };

    // ── * / %
    const parseMul = (): FbThunk => {
      let v = parseUnary();
      while (isOp('*', '/', '%')) {
        const op = toks[pos++].v;
        const left = v, right = parseUnary();
        v = () => {
          const a = fbToNum(left()), b = fbToNum(right());
          if (Number.isNaN(a) || Number.isNaN(b)) { throw new Error(`${op} cần số`); }
          return op === '*' ? a * b : op === '/' ? a / b : a % b;
        };
      }
      return v;
    };

    // ── + -  ('+' nối chuỗi nếu 1 trong 2 vế không phải số)
    const parseAdd = (): FbThunk => {
      let v = parseMul();
      while (isOp('+', '-')) {
        const op = toks[pos++].v;
        const left = v, right = parseMul();
        v = () => {
          const lv = left(), rv = right();
          if (op === '+') {
            return fbIsNum(lv) && fbIsNum(rv) ? fbToNum(lv) + fbToNum(rv) : String(lv) + String(rv);
          }
          const a = fbToNum(lv), b = fbToNum(rv);
          if (Number.isNaN(a) || Number.isNaN(b)) { throw new Error('- cần số'); }
          return a - b;
        };
      }
      return v;
    };

    // ── < <= > >=  (ngày → timestamp · số → số · chuỗi)
    const parseCmp = (): FbThunk => {
      let v = parseAdd();
      while (isOp('<', '<=', '>', '>=')) {
        const op = toks[pos++].v;
        const left = v, right = parseAdd();
        v = () => {
          const c = fbCompare(left(), right());
          return op === '<' ? c < 0 : op === '<=' ? c <= 0 : op === '>' ? c > 0 : c >= 0;
        };
      }
      return v;
    };

    // ── == !=  (cùng luật ép kiểu với so sánh)
    const parseEq = (): FbThunk => {
      let v = parseCmp();
      while (isOp('==', '!=')) {
        const op = toks[pos++].v;
        const left = v, right = parseCmp();
        v = () => {
          const c = fbCompare(left(), right());
          return op === '==' ? c === 0 : c !== 0;
        };
      }
      return v;
    };

    // ── && — short-circuit THẬT: vế phải chỉ được gọi khi vế trái truthy.
    const parseAnd = (): FbThunk => {
      let v = parseEq();
      while (isOp('&&')) {
        pos++;
        const left = v, right = parseEq();
        v = () => (fbTruthy(left()) ? fbTruthy(right()) : false);
      }
      return v;
    };

    // ── || — short-circuit THẬT: vế phải chỉ được gọi khi vế trái falsy.
    const parseOr = (): FbThunk => {
      let v = parseAnd();
      while (isOp('||')) {
        pos++;
        const left = v, right = parseAnd();
        v = () => (fbTruthy(left()) ? true : fbTruthy(right()));
      }
      return v;
    };

    const resultThunk = parseOr();
    if (pos < toks.length) { throw new Error('thừa token cuối công thức'); }
    return resultThunk();
  } catch {
    return '';
  }
}
