/** ───────────────────────────── FORM BUILDER SCHEMA (v2) ─────────────────────────────
 *  Schema JSON thuần (versioned, KHÔNG code động) mô tả form Tạo mới/Sửa/Chi tiết.
 *  v2 (đặc tả No-code/Low-code): Business Rules tập trung (NẾU nhiều điều kiện AND →
 *  THỰC HIỆN nhiều hành động, nhiều field), toán tử so sánh mở rộng, vế phải =
 *  giá trị HOẶC trường dữ liệu, ràng buộc per-type (min/max/format/upload…),
 *  label đa ngôn ngữ VN/EN/CN, Ẩn tĩnh/Readonly, field đặc thù HRM. */

/** Loại field builder hỗ trợ (map 1-1 sang hrm-ui khi render). */
export type FbFieldType =
  | 'text' | 'textarea' | 'number' | 'email' | 'phone'
  | 'select' | 'multiselect' | 'radio' | 'checkbox' | 'toggle'
  | 'date' | 'time' | 'user' | 'rating' | 'upload' | 'image'
  | 'percent' | 'money' | 'address' | 'autocode'
  | 'heading' | 'divider';

/** Toán tử điều kiện (đặc tả: text · ngày · số/giờ · danh sách). */
export type FbOp =
  | 'eq' | 'ne' | 'empty' | 'notEmpty'
  | 'contains' | 'notContains' | 'startsWith' | 'notStartsWith' | 'endsWith' | 'notEndsWith'
  | 'gt' | 'gte' | 'lt' | 'lte'
  | 'dayEq' | 'dayNe'
  | 'inList';

/** Vế phải của điều kiện: nhập giá trị HOẶC so với trường dữ liệu khác. */
export interface FbRhs { kind: 'value' | 'field'; value?: string; field?: string; }

/** 1 điều kiện logic. `value` giữ cho tương thích v1 (rhs kind=value). */
export interface FbCondition { field: string; op: FbOp; rhs?: FbRhs; value?: string; }

/** Loại hành động của Business Rule (đặc tả mục 4). */
export type FbActionType =
  | 'show' | 'hide'
  | 'require' | 'unrequire' | 'readonly' | 'enable'
  | 'setValue' | 'copyValue' | 'compute' | 'warn';

/** 1 hành động — áp lên NHIỀU field (targets = field keys). */
export interface FbAction {
  type: FbActionType;
  targets: string[];
  /** setValue: giá trị gán. */
  value?: string;
  /** copyValue: key field nguồn. */
  fromField?: string;
  /** compute: công thức (IF/ADDDAY/ADDMONTH/ADDYEAR/TODAY + [refs] + toán tử). */
  formula?: string;
  /** warn: nội dung cảnh báo hiển thị dưới field target. */
  message?: string;
}

/** Business Rule tập trung: NẾU (các điều kiện, nối bằng match) → THỰC HIỆN (danh sách hành động).
 *  match: 'all' = mọi điều kiện đúng (VÀ — mặc định) · 'any' = 1 điều kiện đúng là đủ (HOẶC).
 *  Cấp RULE, không per-cặp — tránh mơ hồ precedence (A OR B AND C); cần tổ hợp phức tạp → tách 2 quy tắc. */
export interface FbRule { id: string; name: string; match?: 'all' | 'any'; conditions: FbCondition[]; actions: FbAction[]; }

/** Rule khớp không — dùng chung engine dữ liệu + UI-state. */
export function fbRuleHit(r: FbRule, test: (c: FbCondition) => boolean): boolean {
  if (!r.conditions.length) return false;
  return r.match === 'any' ? r.conditions.some(test) : r.conditions.every(test);
}

/** Hành động khi field đổi giá trị. mode 'formula' (low-code kiểu Power Fx): toValue bỏ qua,
 *  giá trị gán = kết quả `formula` (IF/ADDDAY/[khoá]… — cùng parser với rule compute). */
export interface FbChangeAction { set: string; toValue: string; mode?: 'value' | 'formula'; formula?: string; }

/** Ràng buộc kiểm tra dữ liệu per-type (đặc tả mục 2 — Thông tin riêng). */
export interface FbConstraints {
  /** Số/ngày/giờ: cận dưới/трên (số → numeric; date → dd/MM/yyyy). */
  min?: string;
  max?: string;
  /** Text: độ dài. */
  minLen?: number;
  maxLen?: number;
  /** Text: cấm chứa các giá trị (phân tách dấu phẩy). */
  forbidden?: string;
  /** Number: nguyên hay thập phân. */
  numberFormat?: 'int' | 'decimal';
  /** Date: định dạng hiển thị. */
  dateFormat?: 'dd/MM/yyyy' | 'MM/yyyy' | 'yyyy' | 'HH:mm:ss' | 'HH:mm' | 'mm:ss' | 'custom';
  /** Pattern khi dateFormat = 'custom' (đặc tả Format → Tùy chỉnh). */
  customFormat?: string;
  /** ĐẶC TẢ «Khác các giá trị cụ thể»: CSV giá trị BỊ CẤM — số (Number) hoặc ngày dd/MM/yyyy (Date). */
  excluded?: string;
  /** ĐẶC TẢ «Thứ trong tuần»: CSV thứ CHO PHÉP chọn ('2'..'7', '8'=CN). Rỗng = mọi thứ. */
  weekdays?: string;
  /** ĐẶC TẢ «Ngày lễ/Tết/Ngày nghỉ công ty»: chặn ngày thuộc danh mục nghỉ (demo FB_HOLIDAYS). */
  noHolidays?: boolean;
  /** Upload: giới hạn. */
  maxFiles?: number;
  maxSizeMb?: number;
  fileTypes?: string;
}

/** ─── LOCALE REGISTRY (đặc tả: ngôn ngữ theo DỰ ÁN, không cứng theo field) ───
 *  Registry đầy đủ các ngôn ngữ phần mềm hỗ trợ; mỗi DỰ ÁN bật một tập con
 *  (demo: lưu trong schema.locales — production đọc từ cấu hình tenant).
 *  Phần tử ĐẦU của danh sách bật = ngôn ngữ CHÍNH (fallback mọi bản dịch thiếu). */
export interface FbLocale { key: string; native: string; }
export const FB_LOCALE_REGISTRY: FbLocale[] = [
  { key: 'vi', native: 'Tiếng Việt' },
  { key: 'en', native: 'English' },
  { key: 'cn', native: '中文' },
  { key: 'ja', native: '日本語' },
  { key: 'ko', native: '한국어' },
];
/** Ngôn ngữ bật mặc định của dự án demo. */
export const FB_DEFAULT_LOCALES: string[] = ['vi', 'en'];

/** Nhãn field theo locale: chính = field.label · phụ = field.labels[locale] · legacy labelEn/labelCn. */
export function fbLabelOf(f: { label: string; labels?: Record<string, string>; labelEn?: string; labelCn?: string }, locale: string, defaultLocale = 'vi'): string {
  if (locale === defaultLocale) return f.label;
  const v = f.labels?.[locale] || (locale === 'en' ? f.labelEn : locale === 'cn' ? f.labelCn : '');
  return v || f.label;
}

/** 1 field trong form. */
export interface FbField {
  id: string;
  type: FbFieldType;
  /** Khoá dữ liệu (ngModel key) — sinh từ label, sửa được. */
  key: string;
  /** Nhãn VN (mặc định). */
  label: string;
  /** Bản dịch nhãn theo locale phụ (ngôn ngữ CHÍNH nằm ở `label`). */
  labels?: Record<string, string>;
  /** (legacy v2.0 — migrate vào labels, giữ đọc-tương-thích) */
  labelEn?: string;
  labelCn?: string;
  placeholder?: string;
  /** Chú thích nhỏ dưới field. */
  helper?: string;
  /** Độ rộng theo cột (lưới 6 cột): third=2 · half=3 · twothirds=4 · full=6. */
  span: 'third' | 'half' | 'twothirds' | 'full';
  required?: boolean;
  /** Thông báo bắt buộc nhập tuỳ chỉnh. */
  requiredMsg?: string;
  /** Ẩn TĨNH (đặc tả Hiển thị/Ẩn) — rule show có thể mở lại. */
  hidden?: boolean;
  /** Chỉ đọc TĨNH — rule enable có thể mở lại. */
  readonly?: boolean;
  /** Ràng buộc kiểm tra per-type. */
  constraints?: FbConstraints;
  /** Nguồn dữ liệu danh sách (đặc tả): custom = tự thiết lập · sql/api/enum = nguồn ngoài. */
  datasource?: 'custom' | 'sql' | 'api' | 'enum';
  /** (legacy) chuỗi cấu hình nguồn ngoài — thay bằng dsMeta có cấu trúc. */
  datasourceConfig?: string;
  /** Cấu hình nguồn ngoài CÓ CẤU TRÚC (đặc tả Datasource — phân tích sâu):
   *  sql: chọn stored procedure + mapping cột · api: URL/method/đường dẫn + mapping trường ·
   *  enum: chọn Enum hệ thống (demo load options thật từ registry). */
  dsMeta?: FbDsMeta;
  /** Cho select/multiselect/radio/checkbox: danh sách lựa chọn (datasource "custom"). */
  options?: string[];
  /** Giá trị mặc định. */
  defaultValue?: string;
  /** money: danh sách đơn vị (VD "VNĐ,USD,EUR") + đơn vị mặc định. */
  unitOptions?: string;
  defaultUnit?: string;
  /** autocode: tiền tố sinh mã (VD "G-"). */
  codePrefix?: string;
  /** Logic field-level v1 (giữ tương thích — v2 dùng rules tập trung). */
  visibleWhen?: FbCondition | null;
  requiredWhen?: FbCondition | null;
  onChange?: FbChangeAction[];
  /** LOW-CODE (kiểu ServiceNow Client Script): JavaScript chạy khi field đổi giá trị,
   *  API bảo hộ form.get/form.set + value/oldValue. Demo chạy Function sandbox —
   *  production PHẢI sandbox thật (worker + whitelist). Chạy SAU sự kiện đơn giản, TRƯỚC rules. */
  onChangeScript?: string;
  /** NHÁP: field mới tạo trong builder, CHƯA xuất bản (chưa sinh cột DB thật).
   *  Mô phỏng SAP Custom Fields & Logic: field mặc định (không cờ) coi như cột có sẵn. */
  draft?: boolean;
  /** Khoá không cho sửa/xoá (field hệ thống). */
  locked?: boolean;
}

/** 1 nhóm (section) trong form. */
export interface FbSection {
  id: string;
  title: string;
  fields: FbField[];
}

/** Trang trí giao diện form — THEME PRESET (tham khảo Vueform/Jotform Form Designer).
 *  Chọn 1 preset → đổi màu chủ đạo, nền form, kiểu header (solid/không), sáng/tối, bo góc.
 *  Áp CỤC BỘ qua CSS vars, lưu cùng schema. */
export interface FbTheme {
  /** Key preset trong FB_THEMES ('default' = theo hệ thống). */
  preset?: string;
  /** (giữ tương thích schema cũ — preset ưu tiên hơn) */
  primary?: string;
  sheetBg?: string;
  radius?: 'sharp' | 'default' | 'rounded';
}

/** 1 theme preset. */
export interface FbThemePreset {
  key: string;
  vi: string;
  en: string;
  /** Màu chủ đạo (hex). */
  primary?: string;
  /** Nền tấm form. */
  sheetBg?: string;
  /** Header đầu form: dải MÀU SOLID (tên + mô tả chữ trắng) hay không có. */
  header?: 'solid' | 'none';
  /** Form nền tối (token flip cục bộ qua class .dark). */
  dark?: boolean;
  radius?: 'sharp' | 'default' | 'rounded';
}

/** Bộ theme dựng sẵn. */
export const FB_THEMES: FbThemePreset[] = [
  { key: 'default', vi: 'Mặc định', en: 'Default', header: 'none' },
  { key: 'emerald', vi: 'Ngọc lục', en: 'Emerald', primary: '#16A34A', sheetBg: '#F0FDF4', header: 'solid' },
  { key: 'ocean', vi: 'Đại dương', en: 'Ocean', primary: '#2563EB', sheetBg: '#EFF6FF', header: 'solid' },
  { key: 'sunset', vi: 'Hoàng hôn', en: 'Sunset', primary: '#EA580C', sheetBg: '#FFF7ED', header: 'solid', radius: 'rounded' },
  { key: 'orchid', vi: 'Lan tím', en: 'Orchid', primary: '#7C3AED', sheetBg: '#FAF5FF', header: 'solid', radius: 'rounded' },
  { key: 'midnight', vi: 'Ban đêm', en: 'Midnight', primary: '#8B5CF6', header: 'solid', dark: true },
  { key: 'slate', vi: 'Tối giản', en: 'Minimal', primary: '#475569', sheetBg: '#F8FAFC', header: 'none', radius: 'sharp' },
];

/** Resolve theme của schema → preset hiệu lực (preset ưu tiên; legacy fields = preset ẩn). */
export function fbResolveTheme(t: FbTheme | undefined): FbThemePreset {
  if (t?.preset) return FB_THEMES.find((x) => x.key === t.preset) ?? FB_THEMES[0];
  if (t && (t.primary || t.sheetBg || t.radius)) {
    return { key: 'custom', vi: 'Tuỳ chỉnh', en: 'Custom', primary: t.primary, sheetBg: t.sheetBg, radius: t.radius, header: 'none' };
  }
  return FB_THEMES[0];
}

/** Schema form hoàn chỉnh (v2 — có rules tập trung). */
