/** Options THẬT của field danh sách: custom → options tay · enum → registry (demo load được) ·
 *  sql/api → null (chỉ nối được khi chạy thật). */
export function fbListOptions(f: { datasource?: string; options?: string[]; dsMeta?: FbDsMeta }): string[] | null {
  const ds = f.datasource || 'custom';
  if (ds === 'custom') return f.options || [];
  if (ds === 'enum') return FB_ENUMS[f.dsMeta?.enumName || ''] || null;
  if (ds === 'sql') return FB_SQL_DATA[f.dsMeta?.proc || ''] || null;
  if (ds === 'api') {
    const an = f.dsMeta?.apiName;
    if (an && an !== '__custom') return FB_API_CATALOG[an]?.data || null;
    const url = (f.dsMeta?.url || '').trim();
    if (!url) return null;
    // URL tuỳ chỉnh: mẫu có data riêng; URL lạ → data giả chung (demo luôn sống)
    return FB_API_SAMPLES[url] || ['Dữ liệu API mẫu 1', 'Dữ liệu API mẫu 2', 'Dữ liệu API mẫu 3'];
  }
  return null;
}

