/** Toán tử áp dụng theo loại field (đặc tả: Thành phần → Tình trạng). */
export function fbOpsForType(t: FbFieldType): FbOp[] {
  switch (t) {
    case 'number': case 'percent': case 'money': case 'time': case 'rating':
      return ['empty', 'notEmpty', 'eq', 'ne', 'gt', 'gte', 'lt', 'lte'];
    case 'date':
      return ['empty', 'notEmpty', 'eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'dayEq', 'dayNe'];
    case 'select': case 'multiselect': case 'radio': case 'checkbox': case 'user':
      return ['empty', 'notEmpty', 'eq', 'ne', 'inList'];
    case 'toggle': case 'upload': case 'image':
      return ['empty', 'notEmpty'];
    default: // text/textarea/email/phone/address/autocode
      return ['empty', 'notEmpty', 'eq', 'ne', 'contains', 'notContains', 'startsWith', 'notStartsWith', 'endsWith', 'notEndsWith'];
  }
}

