let seq = 100;
/** Sinh id ngắn cho field/section/rule mới (đủ unique trong 1 schema demo). */
export function fbId(prefix: string): string { return `${prefix}${++seq}`; }

/** Nâng `seq` theo id LỚN NHẤT đã có trong schema — gọi khi load schema từ localStorage,
 *  tránh `seq` reset về 100 mỗi lần reload rồi sinh TRÙNG id với field/section/rule đã lưu. */
function fbSeedSeqFrom(s: FbSchema): void {
  const bump = (id: string) => {
    const n = Number((/(\d+)$/.exec(id) ?? [])[1] ?? 0);
    if (n > seq) seq = n;
  };
  for (const sec of s.sections) { bump(sec.id); for (const f of sec.fields) bump(f.id); }
  for (const r of s.rules) bump(r.id);
}

/** Sinh key dữ liệu từ label (bỏ dấu tiếng Việt → camelCase). */
export function fbKeyFrom(label: string): string {
  const ascii = label.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
  const words = ascii.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').trim().split(/\s+/);
  if (!words.length || !words[0]) return 'field' + Date.now() % 1000;
  return words[0] + words.slice(1).map((w) => w[0].toUpperCase() + w.slice(1)).join('');
}

/** Đọc vế phải điều kiện đã chuẩn hoá (tương thích v1 `value`). */
export function fbRhsOf(c: FbCondition): FbRhs {
  return c.rhs ?? { kind: 'value', value: c.value ?? '' };
}

