/** Ép GIÁ TRỊ MẶC ĐỊNH (string builder lưu) về đúng KIỂU runtime của field —
 *  sửa lỗi: toggle 'true' không bật switch, multiselect CSV không thành mảng,
 *  số rác '1,000' lọt qua validate (NaN → coi như trống). */
export function fbCoerceDefault(t: FbFieldType, v: string): unknown {
  if (v == null || v === '') return undefined;
  switch (t) {
    case 'toggle': return v === 'true' || v === '1' || v === 'Bật' || v === 'On';
    case 'number': case 'percent': case 'money': case 'rating': {
      const n = Number(v.replace(/,/g, ''));
      return Number.isNaN(n) ? undefined : n;
    }
    case 'multiselect': case 'checkbox':
      return v.split(',').map((x) => x.trim()).filter(Boolean);
    case 'date': {
      const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(v.trim());
      if (!m) return undefined;
      const d = new Date(+m[3], +m[2] - 1, +m[1]);
      return d.getDate() === +m[1] ? d : undefined;
    }
    case 'time': {
      const m = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/.exec(v.trim());
      if (!m) return undefined;
      const d = new Date(2000, 0, 1, +m[1], +m[2], +(m[3] || 0));
      return d;
    }
    default: return v;
  }
}

/** Ép giá trị RULE GÁN (setValue string) về đúng kiểu field đích (toggle/number/date). */
export function fbCoerceForType(t: FbFieldType | undefined, v: unknown): unknown {
  if (typeof v !== 'string' || !t) return v;
  const out = fbCoerceDefault(t, v);
  return out === undefined ? v : out;
}

/** Thay 1 [key] trong công thức. */
function fbRenameInFormula(formula: string, oldK: string, newK: string): string {
  return formula.split(`[${oldK}]`).join(`[${newK}]`);
}
/** ĐỔI TÊN key field → cascade toàn schema (rules/điều kiện/công thức/onChange/field-level logic)
 *  — sửa lỗi rename làm mồ côi mọi tham chiếu. */
export function fbRenameKey(schema: FbSchema, oldK: string, newK: string): FbSchema {
  const fixCond = (c: FbCondition): FbCondition => ({
    ...c,
    field: c.field === oldK ? newK : c.field,
    rhs: c.rhs?.kind === 'field' && c.rhs.field === oldK ? { ...c.rhs, field: newK } : c.rhs,
  });
  return {
    ...schema,
    sections: schema.sections.map((sec) => ({
      ...sec,
      fields: sec.fields.map((f) => ({
        ...f,
        visibleWhen: f.visibleWhen ? fixCond(f.visibleWhen) : f.visibleWhen,
        requiredWhen: f.requiredWhen ? fixCond(f.requiredWhen) : f.requiredWhen,
        onChange: f.onChange?.map((a) => (a.set === oldK ? { ...a, set: newK } : a)),
      })),
    })),
    rules: schema.rules.map((r) => ({
      ...r,
      conditions: r.conditions.map(fixCond),
      actions: r.actions.map((a) => ({
        ...a,
        targets: (a.targets || []).map((t) => (t === oldK ? newK : t)),
        fromField: a.fromField === oldK ? newK : a.fromField,
        formula: a.formula ? fbRenameInFormula(a.formula, oldK, newK) : a.formula,
      })),
    })),
  };
}

/** XOÁ field → dọn tham chiếu: điều kiện chứa key chết bị bỏ (rule hết điều kiện → xoá rule),
 *  target chết bị gỡ (action hết target → xoá; rule hết action → xoá), field-level logic reset. */
export function fbCleanupKey(schema: FbSchema, k: string): FbSchema {
  return {
    ...schema,
    sections: schema.sections.map((sec) => ({
      ...sec,
      fields: sec.fields.map((f) => ({
        ...f,
        visibleWhen: f.visibleWhen?.field === k || f.visibleWhen?.rhs?.field === k ? null : f.visibleWhen,
        requiredWhen: f.requiredWhen?.field === k || f.requiredWhen?.rhs?.field === k ? null : f.requiredWhen,
        onChange: f.onChange?.filter((a) => a.set !== k),
      })),
    })),
    rules: schema.rules
      .map((r) => ({
        ...r,
        conditions: r.conditions.filter((c) => c.field !== k && c.rhs?.field !== k),
        actions: r.actions
          .map((a) => ({ ...a, targets: (a.targets || []).filter((t) => t !== k) }))
          .filter((a) => a.targets.length && a.fromField !== k && !(a.formula || '').includes(`[${k}]`)),
      }))
      .filter((r) => r.conditions.length && r.actions.length),
  };
}

const FB_STORE_KEY = 'ds.formBuilder.schema';

/** Nâng schema v1 → v2 (thêm rules rỗng; giữ nguyên field-level logic v1). */
function fbMigrate(parsed: { version?: number; sections?: unknown; rules?: unknown } & Record<string, unknown>): FbSchema | null {
  if (!Array.isArray(parsed?.sections)) return null;
  if (parsed.version === 2 && Array.isArray(parsed.rules)) {
    const sc = parsed as unknown as FbSchema;
    if (!Array.isArray(sc.locales) || !sc.locales.length) sc.locales = [...FB_DEFAULT_LOCALES];
    for (const sec of sc.sections) for (const f of sec.fields) {
      if (!f.labels) {
        const m: Record<string, string> = {};
        if (f.labelEn) m['en'] = f.labelEn;
        if (f.labelCn) m['cn'] = f.labelCn;
        if (Object.keys(m).length) f.labels = m;
      }
    }
    return sc;
  }
  if (parsed.version === 1) return { ...(parsed as object), version: 2, rules: [] } as FbSchema;
  return null;
}

/** Đọc schema đã lưu (localStorage) — hỏng/thiếu → schema mặc định (không bao giờ trắng trang). */
export function fbLoadSchema(): FbSchema {
  try {
    const raw = localStorage.getItem(FB_STORE_KEY);
    if (!raw) return fbDefaultSchema();
    const migrated = fbMigrate(JSON.parse(raw));
    if (migrated) { fbSeedSeqFrom(migrated); return migrated; }
    return fbDefaultSchema();
  } catch { return fbDefaultSchema(); }
}

/** Lưu schema (demo: localStorage; production thay tầng persistence, schema giữ nguyên). */
export function fbSaveSchema(s: FbSchema): void {
  try { localStorage.setItem(FB_STORE_KEY, JSON.stringify(s)); } catch { /* quota/private mode */ }
}
