/** Tra chuỗi UI theo ngôn ngữ; `{x}` thay bằng params. Nhận key locale BẤT KỲ của registry
 *  (vi → VI; en/cn/ja/ko/… → EN vì dict UI chỉ có 2 bản). Key lạ → trả chính key. */
export function fbT(lang: FbLang | string, key: string, params?: Record<string, string | number>): string {
  const e = D[key];
  let s = e ? (lang === 'vi' ? e.vi : e.en) : key;
  if (params) for (const [k, v] of Object.entries(params)) s = s.replace(`{${k}}`, String(v));
  return s;
}
