/** Trạng thái suy ra từ Business Rules cho 1 lần đánh giá (fold theo thứ tự rule). */
interface FbRuleState {
  show: Set<string>; hide: Set<string>;
  require: Set<string>; unrequire: Set<string>;
  readonly: Set<string>; enable: Set<string>;
  warns: Map<string, string[]>;
}

/** ═══════ RULES ENGINE — hàm THUẦN (không phụ thuộc Angular/instance), dùng chung renderer
 *  + host page. Tách khỏi class để host có thể "seed" rules khi mở form (áp gán/tính TRƯỚC
 *  khi renderer kịp mount — sửa lỗi field auto-fill vẫn trống tới khi người dùng sửa field
 *  bất kỳ) mà không phải chờ viewChild. ═══════ */

/** key → loại field (cho fbMatchCond biết Giờ so Giờ chứ không so cả Ngày). */
export type FbTypeOf = (key: string) => FbFieldType | undefined;

function fbParseDMY(s: string): Date | null {
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(s.trim());
  if (!m) return null;
  const d = new Date(+m[3], +m[2] - 1, +m[1]);
  return d.getDate() === +m[1] && d.getMonth() === +m[2] - 1 ? d : null;
}
function fbFmtDMY(d: Date): string {
  return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
}
function fbFmtHM(d: Date): string {
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}
/** Text-like: so sánh bằng/khác theo CHUỖI thuần (không ép số — '01' ≠ '1'). */
function fbIsTextType(t: FbFieldType | undefined): boolean {
  return !t || ['text', 'textarea', 'email', 'phone', 'address', 'autocode', 'select', 'multiselect', 'radio', 'checkbox', 'user'].includes(t);
}
/** Thứ trong tuần theo quy ước VN: 2..7 = T2..T7, 8 = CN. null nếu không phải ngày. */
function fbDayOfWeek(s: string): number | null {
  const d = fbParseDMY(s);
  if (!d) return null;
  const wd = d.getDay(); // 0=CN
  return wd === 0 ? 8 : wd + 1;
}
/** So sánh: cả 2 là ngày dd/MM/yyyy → timestamp; cả 2 là số → numeric; còn lại string
 *  (chuỗi Giờ 'HH:mm' zero-pad tự so đúng thứ tự theo lexicographic). */
function fbCmpVals(a: string, b: string): number {
  const da = fbParseDMY(a), db = fbParseDMY(b);
  if (da && db) return da.getTime() - db.getTime();
  const na = a.trim() !== '' ? Number(a) : NaN, nb = b.trim() !== '' ? Number(b) : NaN;
  if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
  return a < b ? -1 : a > b ? 1 : 0;
}
/** Chuẩn hoá giá trị field → chuỗi so sánh. boolean false/Date-giờ xử lý riêng (không dùng
 *  String() thô): toggle TẮT ≡ '' (đang trống) — TẮT không phải "có giá trị"; field Giờ
 *  format HH:mm (không rơi về dd/MM/yyyy làm mất giờ:phút khi so 2 field Giờ). */
function fbValToStr(v: unknown, isTime: boolean): string {
  if (v == null) return '';
  if (typeof v === 'boolean') return v ? 'true' : '';
  if (Array.isArray(v)) return [...(v as string[])].sort().join(',');
  if (v instanceof Date) return isTime ? fbFmtHM(v) : fbFmtDMY(v);
  return String(v);
}

/** Đánh giá 1 điều kiện với snapshot giá trị + tra loại field (cho so sánh Giờ đúng). */
function fbMatchCond(c: FbCondition | null | undefined, vals: Record<string, unknown>, typeOf: FbTypeOf): boolean {
  if (!c || !c.field) return false;
  const ls = fbValToStr(vals[c.field], typeOf(c.field) === 'time');
  const rhs = fbRhsOf(c);
  const rs = rhs.kind === 'field'
    ? fbValToStr(vals[rhs.field || ''], typeOf(rhs.field || '') === 'time')
    : (rhs.value ?? '');
  switch (c.op) {
    case 'empty': return ls === '';
    case 'notEmpty': return ls !== '';
    case 'eq': return fbIsTextType(typeOf(c.field)) ? ls === rs : fbCmpVals(ls, rs) === 0;
    case 'ne': return fbIsTextType(typeOf(c.field)) ? ls !== rs : fbCmpVals(ls, rs) !== 0;
    case 'contains': return ls.includes(rs);
    case 'notContains': return !ls.includes(rs);
    case 'startsWith': return ls.startsWith(rs);
    case 'notStartsWith': return !ls.startsWith(rs);
    case 'endsWith': return ls.endsWith(rs);
    case 'notEndsWith': return !ls.endsWith(rs);
    case 'gt': return fbCmpVals(ls, rs) > 0;
    case 'gte': return fbCmpVals(ls, rs) >= 0;
    case 'lt': return ls !== '' && fbCmpVals(ls, rs) < 0;
    case 'lte': return ls !== '' && fbCmpVals(ls, rs) <= 0;
    case 'dayEq': return fbDayOfWeek(ls) !== null && String(fbDayOfWeek(ls)) === rs.trim();
    case 'dayNe': return fbDayOfWeek(ls) !== null && String(fbDayOfWeek(ls)) !== rs.trim();
    case 'inList': {
      const list = rs.split(',').map((x) => x.trim()).filter(Boolean);
      const raw = vals[c.field];
      if (Array.isArray(raw)) return (raw as string[]).some((x) => list.includes(String(x).trim()));
      return list.includes(ls.trim());
    }
    default: return false;
  }
}

/** Rule có tham chiếu tới field VỪA ĐỔI không (điều kiện · vế phải field · copy nguồn ·
 *  [ref] trong công thức) — chỉ rule "đang nghe" field dirty mới được đánh giá lại. */
function fbRuleReferences(r: FbRule, dirty: Set<string>): boolean {
  for (const c of r.conditions) {
    if (dirty.has(c.field)) return true;
    const rhs = fbRhsOf(c);
    if (rhs.kind === 'field' && rhs.field && dirty.has(rhs.field)) return true;
  }
  for (const a of r.actions) {
    if (a.type === 'copyValue' && a.fromField && dirty.has(a.fromField)) return true;
    if (a.type === 'compute' && a.formula) {
      const refs = a.formula.match(/\[([^\]]+)\]/g) || [];
      if (refs.some((x) => dirty.has(x.slice(1, -1)))) return true;
    }
  }
  return false;
}

/** Hành động DỮ LIỆU (gán/copy/công thức), hội tụ ≤3 vòng. CHỈ re-run rule khi 1 field nó
 *  THAM CHIẾU vừa đổi (dirty-key filtering) — sửa lỗi rule tái-áp mỗi lần setVal bất kỳ field
 *  nào, khoá cứng field target (không sửa tay được dù không hề readonly). */
export function fbApplyDataRules(
  rules: FbRule[], typeOf: FbTypeOf, start: Record<string, unknown>, dirty: Set<string>,
): Record<string, unknown> {
  let cur = start;
  const dset = new Set(dirty);
  for (let pass = 0; pass < 3; pass++) {
    let changed = false;
    const next = { ...cur };
    for (const r of rules) {
      if (!fbRuleReferences(r, dset)) continue;
      if (!fbRuleHit(r, (c) => fbMatchCond(c, next, typeOf))) continue;
      for (const a of r.actions) {
        for (const t of a.targets || []) {
          let nv: unknown;
          if (a.type === 'setValue') nv = fbCoerceForType(typeOf(t), a.value ?? '');
          else if (a.type === 'copyValue') nv = next[a.fromField || ''] ?? '';
          else if (a.type === 'compute') nv = fbCoerceForType(typeOf(t), fbEvalFormula(a.formula || '', (k) => next[k]));
          else continue;
          if (next[t] !== nv) { next[t] = nv; changed = true; dset.add(t); }
        }
      }
    }
    cur = next;
    if (!changed) break;
  }
  return cur;
}

/** Xây tra-cứu key→type từ schema (cho fbMatchCond/fbApplyDataRules). */
export function fbTypeOfSchema(schema: FbSchema): FbTypeOf {
  const m = new Map<string, FbFieldType>();
  for (const s of schema.sections) for (const f of s.fields) m.set(f.key, f.type);
  return (k) => m.get(k);
}

/** Chạy TOÀN BỘ data rules 1 LẦN cho mọi field (host gọi khi MỞ form mới/prefill record —
 *  KHÔNG phải do người dùng gõ). Hàm THUẦN — host gọi trực tiếp, không cần chờ renderer mount
 *  (sửa lỗi: đặt giá trị mặc định thoả điều kiện rule nhưng field gán/tính vẫn trống lúc mở,
 *  tới khi người dùng sửa field bất kỳ mới đột ngột điền đủ). */
/** Seed GIÁ TRỊ MẶC ĐỊNH đã ÉP KIỂU đúng theo từng field (toggle→bool, số→number,
 *  multi→mảng, date/time→Date) — host (nocode/preview) gọi khi mở form Tạo mới. */
export function fbSeedDefaults(schema: FbSchema): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const sec of schema.sections) for (const f of sec.fields) {
    if (f.defaultValue != null && f.defaultValue !== '') {
      const v = fbCoerceDefault(f.type, f.defaultValue);
      if (v !== undefined) out[f.key] = v;
    }
    if (f.type === 'money' && f.defaultUnit) out[f.key + 'Unit'] = f.defaultUnit;
  }
  return out;
}

export function fbSeedRuleValues(schema: FbSchema, value: Record<string, unknown>): Record<string, unknown> {
  const allKeys = new Set<string>();
  for (const s of schema.sections) for (const f of s.fields) allKeys.add(f.key);
  return fbApplyDataRules(schema.rules || [], fbTypeOfSchema(schema), value, allKeys);
}

/** sg-form-renderer — RENDER RUNTIME của FormSchema v2: map field.type → component hrm-ui thật.
 *  Dùng ở 3 chỗ (1 nguồn duy nhất, preview không bao giờ lệch runtime):
 *   1. Canvas builder (preview tĩnh riêng) · 2. Xem trước builder (logic sống) ·
 *   3. Form Tạo mới/Sửa/Chi tiết trang No-code — đủ 5 surface hrm-detail-peek.
 *  v2: BUSINESS RULES tập trung (điều kiện AND, hành động đa field: ẩn/hiện/bắt buộc/
 *  readonly/gán/copy/công thức/cảnh báo) + ràng buộc per-type validate sống + label đa
 *  ngôn ngữ + field đặc thù (chọn nhiều, %, tiền tệ, địa chỉ, mã tự sinh). */
@Component({
  selector: 'sg-form-renderer',
  imports: [
    FormsModule, TablerIconComponent,
    HrmInput, HrmInputNumber, HrmTextarea, HrmSelect, HrmRadioGroup,
    HrmCheckbox, HrmSwitch, HrmDatePicker, HrmTimePicker, HrmRate,
  ],
  template: `
    <!-- Header SOLID theo theme preset — tên + mô tả form trên nền màu chủ đạo -->
    @if (thPreset().header === 'solid') {
      <div class="fbr-head" [style.background]="thPrimary() || 'var(--primary-base)'">
        <div class="fbr-head-t">{{ schema().name }}</div>
        @if (schema().desc) { <div class="fbr-head-d">{{ schema().desc }}</div> }
      </div>
    }
    <div class="fbr-body" [class.dark]="thPreset().dark" [style.background]="thBg()">
      @for (w of hiddenWarns(); track w) {
        <div class="fbr-err fbr-err--top"><tabler-icon [icon]="icWarn" [size]="13" /> {{ tr('rHiddenWarn') }} {{ w }}</div>
      }
      @for (sec of schema().sections; track sec.id) {
        <section class="fbr-sec">
          @if (sec.title) { <div class="fbr-sec-h">{{ sec.title }}</div> }
          <div class="fbr-grid">
            @for (f of sec.fields; track f.id) {
              @if (isVisible(f)) {
                @switch (f.type) {
                  @case ('heading') { <div class="fbr-heading fbr-span-full">{{ labelOf(f) }}</div> }
                  @case ('divider') { <hr class="fbr-divider fbr-span-full" /> }
                  @default {
                    <label class="fbr-field" [style.gridColumn]="'span ' + spanCols(f)">
                      <span class="fbr-lbl">{{ labelOf(f) }}
                        @if (isRequired(f)) { <b class="fbr-req">*</b> }
                      </span>

                      @if (mode() === 'detail' || isReadonly(f)) {
                        <span class="fbr-ro" [class.fbr-ro--boxed]="mode() !== 'detail'">{{ displayValue(f) }}</span>
                      } @else {
                        @switch (f.type) {
                          @case ('text') { <hrm-input [name]="f.id" [ngModel]="str(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || ''" [maxlength]="f.constraints?.maxLen || null" /> }
                          @case ('address') { <hrm-input [name]="f.id" [ngModel]="str(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || ''" [maxlength]="f.constraints?.maxLen || null" /> }
                          @case ('email') { <hrm-input [name]="f.id" htmlType="email" [ngModel]="str(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || ''" [maxlength]="f.constraints?.maxLen || null" /> }
                          @case ('phone') { <hrm-input [name]="f.id" htmlType="tel" [ngModel]="str(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || ''" [maxlength]="f.constraints?.maxLen || null" /> }
                          @case ('number') { <hrm-input-number [name]="f.id" [ngModel]="num(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || ''" [min]="conMinNum(f)" [max]="conMaxNum(f)" [precision]="f.constraints?.numberFormat === 'int' ? 0 : null" /> }
                          @case ('percent') { <hrm-input-number [name]="f.id" [ngModel]="num(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || ''" [min]="conMinNum(f)" [max]="conMaxNum(f)" unit="%" /> }
                          @case ('money') {
                            <span class="fbr-money">
                              <hrm-input-number class="fbr-money-n" [name]="f.id" [ngModel]="num(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || '0'" [min]="conMinNum(f)" [max]="conMaxNum(f)" />
                              <hrm-select class="fbr-money-u" [name]="f.id + 'Unit'" [ngModel]="unitVal(f)" (ngModelChange)="setUnit(f, $event)" [options]="unitOpts(f)" [allowClear]="false" [showSearch]="false" />
                            </span>
                          }
                          @case ('autocode') { <span class="fbr-ro fbr-ro--boxed fbr-mono">{{ autoCode(f) }}</span> }
                          @case ('textarea') { <hrm-textarea [name]="f.id" [ngModel]="str(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || ''" [maxlength]="f.constraints?.maxLen || null" /> }
                          @case ('select') { <hrm-select [name]="f.id" [ngModel]="str(f) || null" (ngModelChange)="setVal(f, $event)" [options]="opts(f)" [placeholder]="f.placeholder || tr('rSelectPh')" /> }
                          @case ('multiselect') { <hrm-select [name]="f.id" [multiple]="true" [ngModel]="arr(f)" (ngModelChange)="setVal(f, $event)" [options]="opts(f)" [placeholder]="f.placeholder || tr('rMultiPh')" /> }
                          @case ('radio') { <hrm-radio-group [name]="f.id" [ngModel]="str(f)" (ngModelChange)="setVal(f, $event)" [options]="opts(f)" /> }
                          @case ('checkbox') {
                            <span class="fbr-checks">
                              @for (o of f.options || []; track o) {
                                <hrm-checkbox [name]="f.id + o" [ngModel]="isChecked(f, o)" (ngModelChange)="toggleCheck(f, o, $event)">{{ o }}</hrm-checkbox>
                              }
                            </span>
                          }
                          @case ('toggle') { <span class="fbr-toggle"><hrm-switch [name]="f.id" [ngModel]="bool(f)" (ngModelChange)="setVal(f, $event)" /></span> }
                          @case ('date') { <hrm-date-picker [name]="f.id" [ngModel]="anyVal(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || 'dd/MM/yyyy'" [format]="dateFmt(f)" [disabledDate]="dateDisabled(f)" /> }
                          @case ('time') { <hrm-time-picker [name]="f.id" [ngModel]="anyVal(f)" (ngModelChange)="setVal(f, $event)" [placeholder]="f.placeholder || 'hh:mm'" [format]="timeFormat(f)" /> }
                          @case ('user') { <hrm-select [name]="f.id" [ngModel]="str(f) || null" (ngModelChange)="setVal(f, $event)" [options]="f.options?.length ? opts(f) : userOpts" [placeholder]="f.placeholder || tr('rUserPh')" /> }
                          @case ('rating') { <span class="fbr-rate"><hrm-rate [name]="f.id" [ngModel]="num(f) || 0" (ngModelChange)="setVal(f, $event)" [count]="conMaxNum(f) === Infinity ? 5 : conMaxNum(f)" /></span> }
                          @case ('upload') {
                            @if (arr(f).length) {
                              <span class="fbr-files">
                                @for (fn of arr(f); track fn) {
                                  <span class="fbr-file">{{ fn }}
                                    <!-- preventDefault: chặn label forward click sang nút × (labelable đầu tiên) -->
                                    <button type="button" class="fbr-file-x" (click)="removeFile(f, fn); $event.preventDefault(); $event.stopPropagation()">×</button>
                                  </span>
                                }
                              </span>
                            }
                            <!-- Vùng thả còn hiện tới khi ĐỦ Số lượng file (đặc tả Upload → Giới hạn) -->
                            @if (arr(f).length < maxFilesOf(f)) {
                              <span class="fbr-upload" (click)="pickDemoFile(f); $event.preventDefault()">
                                <tabler-icon [icon]="icUpload" [size]="22" />
                                <span class="fbr-upload-t">{{ tr('rUpload1') }} <b>{{ tr('rUpload2') }}</b></span>
                              </span>
                            } @else {
                              <span class="fbr-hint">{{ tr('rMaxFilesHit', { n: maxFilesOf(f) }) }}</span>
                            }
                          }
                          @case ('image') {
                            <span class="fbr-upload fbr-upload--img">
                              <tabler-icon [icon]="icPhoto" [size]="22" />
                              <span class="fbr-upload-t">{{ tr('rImage') }}</span>
                            </span>
                          }
                        }
                      }

                      @if (uploadLimit(f); as lim) { <span class="fbr-help">{{ lim }}</span> }
                      @if (f.helper && mode() !== 'detail') { <span class="fbr-help">{{ f.helper }}</span> }
                      @if (mode() !== 'detail') {
                        @if (requiredError(f); as rerr) {
                          <span class="fbr-err"><tabler-icon [icon]="icWarn" [size]="13" /> {{ rerr }}</span>
                        } @else if (constraintError(f); as err) {
                          <span class="fbr-err"><tabler-icon [icon]="icWarn" [size]="13" /> {{ err }}</span>
                        }
                        @for (w of warnsOf(f); track w) {
                          <span class="fbr-err"><tabler-icon [icon]="icWarn" [size]="13" /> {{ w }}</span>
                        }
                      }
                    </label>
                  }
                }
              }
            }
          </div>
        </section>
      }
    </div>
  `,
  host: {
    class: 'sg-form-renderer',
    // Trang trí form (schema.theme) — override CSS vars CỤC BỘ trong phạm vi form.
    '[style.--primary-base]': 'thPrimary()',
    '[style.--radius-md]': 'thRadiusMd()',
    '[style.--radius-lg]': 'thRadiusLg()',
  },
  styles: [`
    :host { display: block; }
    /* Header solid theo theme — dải màu chủ đạo, chữ trắng. */
    .fbr-head { padding: 16px 20px 14px; color: var(--static-white, #fff); }
    .fbr-head-t { font-size: var(--fs-16, 16px); font-weight: var(--font-bold, 700); }
    .fbr-head-d { margin-top: 2px; font-size: var(--fs-12, 12px); opacity: .85; }
    /* Mật độ CHUẨN form list-page: body 20/20/12 · section gap 24 · grid 6 cột (Vueform columns). */
    .fbr-body { padding: var(--space-5, 20px) var(--space-5, 20px) var(--space-3, 12px); display: flex; flex-direction: column; gap: var(--space-6, 24px); }
    .fbr-sec { display: flex; flex-direction: column; gap: var(--space-3, 12px); }
    .fbr-sec-h { font-size: var(--fs-13, 13px); font-weight: var(--font-bold, 700); color: var(--text-strong); padding-bottom: 8px; border-bottom: 1px solid var(--border-soft); }
    .fbr-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 14px 10px; }
    .fbr-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
    .fbr-span-full { grid-column: 1 / -1; }
    .fbr-lbl { font-size: var(--fs-13, 13px); font-weight: var(--font-medium, 500); color: var(--text-strong); }
    .fbr-req { color: var(--error-base); font-weight: var(--font-bold, 700); }
    .fbr-help { font-size: var(--fs-12, 12px); color: var(--text-soft); }
    /* Lỗi ràng buộc / cảnh báo rule — đỏ semantic, icon + text. */
    .fbr-err { display: inline-flex; align-items: center; gap: 4px; font-size: var(--fs-12, 12px); color: var(--error-base); }

    .fbr-heading { font-size: var(--fs-14, 14px); font-weight: var(--font-bold, 700); color: var(--text-strong); padding-top: 4px; }
    .fbr-divider { border: 0; border-top: 1px solid var(--border-soft); margin: 2px 0; width: 100%; }

    .fbr-checks { display: flex; flex-direction: column; gap: 6px; padding-top: 2px; }
    .fbr-toggle, .fbr-rate { display: inline-flex; align-items: center; min-height: 32px; }

    /* Số tiền = group control: số (co giãn) + đơn vị tiền tệ (cố định). */
    .fbr-money { display: flex; gap: 8px; min-width: 0; }
    .fbr-money-n { flex: 1 1 auto; min-width: 0; }
    .fbr-money-u { flex: 0 0 96px; }
    .fbr-mono { font-family: var(--font-mono, ui-monospace, monospace); }

    /* Vùng upload/hình — dashed drop area theo token, KHÔNG upload thật (demo). */
    .fbr-upload {
      display: flex; align-items: center; justify-content: center; gap: 10px;
      min-height: 74px; border: 1.5px dashed var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface-subtle); color: var(--text-sub); cursor: pointer;
      transition: border-color var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out);
    }
    .fbr-upload:hover { border-color: var(--primary-base); color: var(--primary-base); }
    .fbr-upload-t b { font-weight: var(--font-semibold, 600); color: var(--primary-base); }

    /* Chế độ CHI TIẾT / READONLY — giá trị dạng text; readonly trong form có khung nhạt. */
    .fbr-ro { font-size: var(--fs-14, 14px); color: var(--text-body); min-height: 22px; white-space: pre-wrap; }
    .fbr-err--top { padding: 8px 10px; border: 1px solid color-mix(in srgb, var(--error-base) 35%, transparent); border-radius: var(--radius-md); background: color-mix(in srgb, var(--error-base) 6%, var(--bg-surface)); }
    .fbr-hint { font-size: var(--fs-12); color: var(--text-sub); }
    .fbr-files { display: flex; flex-wrap: wrap; gap: 6px; }
    .fbr-file { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface-subtle); font-size: var(--fs-12); color: var(--text-body); }
    .fbr-file-x { border: 0; background: transparent; color: var(--text-soft); cursor: pointer; font-size: 14px; line-height: 1; padding: 0; }
    .fbr-file-x:hover { color: var(--error-base); }
    .fbr-ro--boxed { display: flex; align-items: center; min-height: 32px; padding: 0 11px;
      border: 1px solid var(--border-soft); border-radius: var(--radius-md);
      background: var(--bg-surface-subtle); color: var(--text-sub); }
  `],
})
export class SgFormRenderer {
  readonly schema = input.required<FbSchema>();
  /** create = form trống theo default · edit = prefill từ [value] · detail = read-only. */
  readonly mode = input<'create' | 'edit' | 'detail'>('create');
  /** Ngôn ngữ label — key locale bất kỳ trong registry dự án (vi/en/cn/ja/ko…). */
  readonly lang = input<string>('vi');
  /** Dữ liệu form (key → giá trị). Two-way. */
  readonly value = model<Record<string, unknown>>({});

  protected readonly icUpload = IconCloudUpload;
  protected readonly icPhoto = IconPhoto;
  protected readonly icWarn = IconAlertTriangle;
  /** Options demo cho field Nhân viên. */
  protected readonly userOpts: HrmOption[] = [
    'Nguyễn Văn A', 'Trần Thị B', 'Lê Văn C', 'Phạm Thu D', 'Đỗ Minh E', 'Vũ Hải F',
  ].map((n) => ({ value: n, label: n }));

  /** Đã bấm Lưu chưa — chỉ hiện lỗi "bắt buộc nhập" SAU lần Lưu đầu (không doạ người dùng
   *  ngay khi vừa mở form trống). */
  private readonly submitted = signal(false);

  /** key→type (memo theo schema) — cho so sánh Giờ đúng kiểu trong fbMatchCond. */
  private readonly typeOfFn = computed<FbTypeOf>(() => fbTypeOfSchema(this.schema()));

  /** Chuỗi UI theo ngôn ngữ (dict _fb-i18n — VI thuần Việt · EN thuần Anh, không trộn). */
  protected tr(key: string, params?: Record<string, string | number>): string {
    return fbT(this.lang(), key, params);
  }

  // ── trang trí form (schema.theme → PRESET hiệu lực) → CSS vars cục bộ ──
  protected readonly thPreset = computed(() => fbResolveTheme(this.schema().theme));
  protected readonly thPrimary = computed(() => this.thPreset().primary || null);
  protected readonly thBg = computed(() => {
    const t = this.thPreset();
    if (t.dark) return 'var(--bg-surface)';
    return t.sheetBg || null;
  });
  protected readonly thRadiusMd = computed(() => {
    const r = this.thPreset().radius;
    return r === 'sharp' ? '2px' : r === 'rounded' ? '10px' : null;
  });
  protected readonly thRadiusLg = computed(() => {
    const r = this.thPreset().radius;
    return r === 'sharp' ? '4px' : r === 'rounded' ? '14px' : null;
  });

  /** Nhãn theo locale đang chọn — fallback về ngôn ngữ CHÍNH của dự án (schema.locales[0]). */
  protected labelOf(f: FbField): string {
    const def = this.schema().locales?.[0] ?? 'vi';
    return fbLabelOf(f, this.lang(), def);
  }

  /** Map field.options → HrmOption[]. Datasource NGOÀI (sql/api/enum) → option placeholder
   *  disabled ghi rõ nguồn (demo — runtime nối nguồn thật). */
  protected opts(f: FbField): HrmOption[] {
    // Nguồn ngoài có DATA GIẢ (enum registry / proc / API mẫu) → load danh sách thật trong demo;
    // chưa cấu hình nguồn → placeholder "kết nối khi chạy thật".
    const list = fbListOptions(f);
    if (list === null) {
      const ds = (f.datasource || 'custom').toUpperCase();
      return [{ value: '', label: this.tr('dsRuntime', { ds }), disabled: true }];
    }
    return list.map((o) => ({ value: o, label: o }));
  }
  protected unitOpts(f: FbField): HrmOption[] {
    return (f.unitOptions || 'VNĐ').split(',').map((u) => u.trim()).filter(Boolean).map((u) => ({ value: u, label: u }));
  }

  /** span → số cột trên lưới 6 (Vueform columns). */
  protected spanCols(f: FbField): number {
    return f.span === 'third' ? 2 : f.span === 'twothirds' ? 4 : f.span === 'full' ? 6 : 3;
  }
  /** Format Giờ hiệu lực — chỉ nhận 3 giá trị hợp lệ (schema có thể lưu format của loại field
   *  KHÁC sau khi builder đổi type field) — sai/thiếu → HH:mm mặc định. */
  protected timeFormat(f: FbField): string {
    const fmt = f.constraints?.dateFormat;
    return fmt === 'HH:mm:ss' || fmt === 'mm:ss' ? fmt : 'HH:mm';
  }

  // ── đọc giá trị theo kiểu — check "key CÓ trong map" (không phải "== null") để:
  // (a) defaultValue hiện đúng cho MỌI loại field (không chỉ text), (b) select bị CLEAR
  // (giá trị null tường minh) không bị defaultValue "hồi sinh" lại mỗi lần render. ──
  protected anyVal(f: FbField): unknown {
    const vals = this.value();
    if (f.key in vals) return vals[f.key] ?? null;
    if (f.defaultValue && f.type === 'date') return fbParseDMY(f.defaultValue);
    return null;
  }
  protected str(f: FbField): string {
    const vals = this.value();
    if (!(f.key in vals)) return f.defaultValue ?? '';
    const v = vals[f.key];
    return v == null ? '' : String(v);
  }
  protected num(f: FbField): number | null {
    const vals = this.value();
    const raw = f.key in vals ? vals[f.key] : f.defaultValue;
    if (typeof raw === 'number') return raw;
    if (typeof raw === 'string' && raw.trim() !== '' && !Number.isNaN(Number(raw))) return Number(raw);
    return null;
  }
  protected bool(f: FbField): boolean {
    const vals = this.value();
    if (!(f.key in vals)) return f.defaultValue === 'true';
    return vals[f.key] === true;
  }
  protected arr(f: FbField): string[] {
    const v = this.value()[f.key];
    return Array.isArray(v) ? (v as string[]) : [];
  }
  protected unitVal(f: FbField): string { return String(this.value()[f.key + 'Unit'] ?? f.defaultUnit ?? 'VNĐ'); }
  protected isChecked(f: FbField, o: string): boolean {
    const v = this.value()[f.key];
    return Array.isArray(v) && (v as string[]).includes(o);
  }
  /** Mã tự sinh: hiện giá trị đã sinh (host điền lúc mở form Tạo mới), hoặc placeholder khi
   *  chưa có (VD canvas builder — chưa gắn vào form runtime nào). */
  protected autoCode(f: FbField): string {
    const v = this.value()[f.key];
    return v != null && v !== '' ? String(v) : `${f.codePrefix || 'AUTO-'}${this.tr('rAutoGen')}`;
  }
  /** Text mô tả giới hạn upload từ constraints (đặc tả: số file/dung lượng/định dạng). */
  protected uploadLimit(f: FbField): string | null {
    if (f.type !== 'upload' || this.mode() === 'detail') return null;
    const c = f.constraints; if (!c) return null;
    const parts: string[] = [];
    if (c.fileTypes) parts.push(c.fileTypes.toUpperCase().split(',').map((x) => x.trim()).join(', '));
    if (c.maxSizeMb) parts.push(this.tr('rMaxPerFile', { n: c.maxSizeMb }));
    if (c.maxFiles) parts.push(this.tr('rMaxFiles', { n: c.maxFiles }));
    return parts.length ? parts.join(' · ') : null;
  }

  /** Ghi giá trị + chạy RULES (gán/copy/công thức) CHỈ cho rule tham chiếu field vừa đổi
   *  (dirty-key filtering — field khác không hề "nghe" field này thì không bị đè lại). */
  protected setVal(f: FbField, v: unknown): void {
    const oldValue = this.value()[f.key];
    let next: Record<string, unknown> = { ...this.value(), [f.key]: v };
    const tof = this.typeOfFn();
    for (const act of f.onChange || []) {
      if (!act.set) continue;
      // mode 'formula' (low-code A): gán = kết quả công thức — cùng parser với rule compute
      const raw = act.mode === 'formula'
        ? fbEvalFormula(act.formula || '', (k) => next[k])
        : act.toValue;
      next[act.set] = fbCoerceForType(tof(act.set), raw);
    }
    // Script nâng cao (low-code B — kiểu ServiceNow g_form): API bảo hộ, lỗi script KHÔNG vỡ form.
    // Demo dùng Function sandbox; production PHẢI thay bằng worker + whitelist API.
    if (f.onChangeScript?.trim()) {
      try {
        const api = {
          get: (k: string) => next[k],
          set: (k: string, val: unknown) => { next[k] = fbCoerceForType(tof(k), val == null ? '' : String(val)); },
        };
        new Function('form', 'value', 'oldValue', f.onChangeScript)(api, next[f.key], oldValue);
      } catch { /* script lỗi → bỏ qua, form tiếp tục */ }
    }
    next = fbApplyDataRules(this.schema().rules || [], this.typeOfFn(), next, new Set([f.key]));
    this.value.set(next);
  }
  protected setUnit(f: FbField, u: string): void {
    const key = f.key + 'Unit';
    const next = fbApplyDataRules(this.schema().rules || [], this.typeOfFn(), { ...this.value(), [key]: u }, new Set([key]));
    this.value.set(next);
  }
  protected toggleCheck(f: FbField, o: string, on: boolean): void {
    const cur = this.value()[f.key];
    const list = Array.isArray(cur) ? [...(cur as string[])] : [];
    const i = list.indexOf(o);
    if (on && i < 0) list.push(o);
    if (!on && i >= 0) list.splice(i, 1);
    this.setVal(f, list);
  }

  /** Trạng thái UI suy ra từ rules (fold THEO THỨ TỰ — rule sau thắng rule trước). Luôn đánh
   *  giá LẠI TOÀN BỘ rule (không dirty-gate) — đây là UI-state phái sinh thuần, không có tác
   *  dụng phụ ghi đè giá trị nên không có rủi ro "khoá cứng field" như nhánh dữ liệu. */
  private readonly ruleState = computed<FbRuleState>(() => {
    const st: FbRuleState = {
      show: new Set(), hide: new Set(), require: new Set(), unrequire: new Set(),
      readonly: new Set(), enable: new Set(), warns: new Map(),
    };
    const vals = this.value();
    const typeOf = this.typeOfFn();
    for (const r of this.schema().rules || []) {
      if (!fbRuleHit(r, (c) => fbMatchCond(c, vals, typeOf))) continue;
      for (const a of r.actions) {
        for (const t of a.targets || []) {
          switch (a.type) {
            case 'show': st.show.add(t); st.hide.delete(t); break;
            case 'hide': st.hide.add(t); st.show.delete(t); break;
            case 'require': st.require.add(t); st.unrequire.delete(t); break;
            case 'unrequire': st.unrequire.add(t); st.require.delete(t); break;
            case 'readonly': st.readonly.add(t); st.enable.delete(t); break;
            case 'enable': st.enable.add(t); st.readonly.delete(t); break;
            case 'warn': {
              const list = st.warns.get(t) || [];
              if (a.message) list.push(a.message);
              st.warns.set(t, list);
              break;
            }
          }
        }
      }
    }
    return st;
  });

  // ── hiển thị / bắt buộc / readonly (tĩnh + v1 field-level + rules) ──
  protected isVisible(f: FbField): boolean {
    const st = this.ruleState();
    if (st.hide.has(f.key)) return false;
    if (st.show.has(f.key)) return true;
    if (f.hidden) return false;
    return f.visibleWhen ? fbMatchCond(f.visibleWhen, this.value(), this.typeOfFn()) : true;
  }
  protected isRequired(f: FbField): boolean {
    const st = this.ruleState();
    if (st.unrequire.has(f.key)) return false;
    if (st.require.has(f.key)) return true;
    return !!f.required || (f.requiredWhen ? fbMatchCond(f.requiredWhen, this.value(), this.typeOfFn()) : false);
  }
  protected isReadonly(f: FbField): boolean {
    const st = this.ruleState();
    if (st.enable.has(f.key)) return false;
    if (st.readonly.has(f.key)) return true;
    return !!f.readonly || f.type === 'autocode';
  }
  protected warnsOf(f: FbField): string[] { return this.ruleState().warns.get(f.key) || []; }

  /** Field bắt buộc còn TRỐNG không (mảng rỗng/chuỗi rỗng/null; toggle luôn có giá trị hợp lệ). */
  private isEmptyValue(f: FbField): boolean {
    const v = this.value()[f.key];
    if (Array.isArray(v)) return v.length === 0;
    if (typeof v === 'boolean') return false;
    return v == null || v === '';
  }
  /** Lỗi "bắt buộc nhập" — CHỈ hiện sau khi đã bấm Lưu 1 lần (submitted); dùng requiredMsg
   *  tuỳ chỉnh nếu có, else thông báo mặc định. */
  protected requiredError(f: FbField): string | null {
    if (!this.submitted() || this.mode() === 'detail') return null;
    if (!this.isVisible(f) || !this.isRequired(f) || this.isReadonly(f)) return null;
    if (!this.isEmptyValue(f)) return null;
    return f.requiredMsg || this.tr('rRequired', { label: this.labelOf(f) });
  }
  /** Host gọi khi MỞ form mới — tắt hiện lỗi bắt buộc của lần Lưu trước. */
  resetValidation(): void { this.submitted.set(false); }
  /** Host gọi TRƯỚC khi lưu — trả false nếu có field bắt buộc còn trống / vi phạm ràng buộc
   *  (và bật hiện lỗi trên form). true → cho phép lưu. */
  validate(): boolean {
    this.submitted.set(true);
    let ok = true;
    for (const s of this.schema().sections) {
      for (const f of s.fields) {
        if (f.type === 'heading' || f.type === 'divider') continue;
        if (!this.isVisible(f)) continue;
        if (this.requiredError(f) || this.constraintError(f)) ok = false;
      }
    }
    return ok;
  }

  // ── VALIDATE ràng buộc per-type (sống — chỉ khi ĐÃ có giá trị vi phạm) ──
  protected constraintError(f: FbField): string | null {
    const raw = this.value()[f.key];
    const s = raw == null ? '' : raw instanceof Date ? fbFmtDMY(raw) : String(raw);
    if (s === '') return null;
    // Kiểm tra ĐỊNH DẠNG theo loại field — chạy cả khi KHÔNG có constraints.
    if (f.type === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)) return this.tr('rEmailFmt');
    if (f.type === 'phone' && !/^[0-9+()\s.-]{8,15}$/.test(s)) return this.tr('rPhoneFmt');
    const c = f.constraints; if (!c) return null;
    const isNum = f.type === 'number' || f.type === 'percent' || f.type === 'money' || f.type === 'rating';
    if (isNum) {
      const n = Number(s);
      if (!Number.isNaN(n)) {
        if (c.numberFormat === 'int' && !Number.isInteger(n)) return this.tr('rIntOnly');
        if (c.min != null && c.min !== '' && n < Number(c.min)) return this.tr('rMinVal', { n: c.min });
        if (c.max != null && c.max !== '' && n > Number(c.max)) return this.tr('rMaxVal', { n: c.max });
        // ĐẶC TẢ «Khác các giá trị cụ thể» — so THEO SỐ (0 ≡ 0.0)
        if (c.excluded && c.excluded.split(',').some((x) => x.trim() !== '' && Number(x) === n)) return this.tr('rNumExcluded', { n: s });
      }
      return null;
    }
    if (f.type === 'date') {
      const d = fbParseDMY(s); if (!d) return null;
      const mn = c.min ? fbParseDMY(c.min) : null;
      const mx = c.max ? fbParseDMY(c.max) : null;
      if (mn && d.getTime() < mn.getTime()) return this.tr('rNotBefore', { n: c.min });
      if (mx && d.getTime() > mx.getTime()) return this.tr('rNotAfter', { n: c.max });
      // ĐẶC TẢ Date: thứ cho phép · ngày lễ/nghỉ · loại trừ ngày cụ thể (đề phòng giá trị vào ngoài picker)
      const wds = (c.weekdays || '').split(',').map((x) => x.trim()).filter(Boolean);
      if (wds.length) {
        const wd = d.getDay() === 0 ? '8' : String(d.getDay() + 1);
        if (!wds.includes(wd)) return this.tr('rWeekdayNot');
      }
      if (c.noHolidays && fbIsHoliday(d)) return this.tr('rHoliday');
      if (c.excluded && c.excluded.split(',').map((x) => x.trim()).includes(fbFmtDMY(d))) return this.tr('rDateExcluded');
      return null;
    }
    if (f.type === 'time') {
      const hm = raw instanceof Date ? `${String(raw.getHours()).padStart(2, '0')}:${String(raw.getMinutes()).padStart(2, '0')}` : s;
      if (c.min && hm < c.min) return this.tr('rTimeMin', { n: c.min });
      if (c.max && hm > c.max) return this.tr('rTimeMax', { n: c.max });
      return null;
    }
    // text-like
    if (c.minLen != null && c.minLen > 0 && s.length < c.minLen) return this.tr('rMinLen', { n: c.minLen });
    if (c.maxLen != null && c.maxLen > 0 && s.length > c.maxLen) return this.tr('rMaxLen', { n: c.maxLen });
    if (c.forbidden) {
      const bad = c.forbidden.split(',').map((x) => x.trim()).filter(Boolean).find((x) => s.includes(x));
      if (bad) return this.tr('rForbidden', { n: bad });
    }
    return null;
  }

  /** Cảnh báo của các field ĐANG ẨN (warn rule) — gom hiện đầu form, không nuốt mất. */
  protected readonly hiddenWarns = computed<string[]>(() => {
    const out: string[] = [];
    for (const sec of this.schema().sections) for (const f of sec.fields) {
      if (!this.isVisible(f)) out.push(...this.warnsOf(f));
    }
    return out;
  });

  /** disabledDate cho hrm-date-picker theo constraints min/max (dd/MM/yyyy). */
  /** Closure cache theo min/max — tham chiếu ổn định, tránh loop CD zoneless. */
  private readonly _ddCache = new Map<string, (d: Date) => boolean>();
  protected dateDisabled(f: FbField): ((d: Date) => boolean) | undefined {
    const c = f.constraints;
    if (!c?.min && !c?.max && !c?.weekdays && !c?.noHolidays && !c?.excluded) return undefined;
    const k = [c.min, c.max, c.weekdays, c.noHolidays ? 'H' : '', c.excluded].map((x) => x || '').join('|');
    let fn = this._ddCache.get(k);
    if (!fn) {
      const mn = c.min ? fbParseDMY(c.min) : null;
      const mx = c.max ? fbParseDMY(c.max) : null;
      // Thứ CHO PHÉP ('2'..'8', 8=CN) — rỗng = mọi thứ; ngày BỊ LOẠI TRỪ (dd/MM/yyyy CSV)
      const wds = (c.weekdays || '').split(',').map((x) => x.trim()).filter(Boolean);
      const excl = new Set((c.excluded || '').split(',').map((x) => x.trim()).filter(Boolean));
      const noHol = !!c.noHolidays;
      fn = (d: Date) => {
        if (mn && d.getTime() < mn.getTime()) return true;
        if (mx && d.getTime() > mx.getTime()) return true;
        if (wds.length) {
          const wd = d.getDay() === 0 ? '8' : String(d.getDay() + 1);
          if (!wds.includes(wd)) return true;
        }
        if (noHol && fbIsHoliday(d)) return true;
        if (excl.size && excl.has(fbFmtDMY(d))) return true;
        return false;
      };
      this._ddCache.set(k, fn);
    }
    return fn;
  }

  /** Format hiển thị date: preset hoặc pattern Tùy chỉnh (đặc tả Format → Tùy chỉnh). */
  protected dateFmt(f: FbField): string {
    const c = f.constraints;
    if (c?.dateFormat === 'custom') return c.customFormat || 'dd/MM/yyyy';
    return c?.dateFormat || 'dd/MM/yyyy';
  }
  /** Upload demo: đính tệp mẫu — TÔN TRỌNG giới hạn Số lượng file (đặc tả Upload). */
  protected pickDemoFile(f: FbField): void {
    if (this.arr(f).length >= this.maxFilesOf(f)) return;
    const n = this.arr(f).length + 1;
    this.setVal(f, [...this.arr(f), `tai-lieu-demo-${n}.pdf`]);
  }
  protected maxFilesOf(f: FbField): number {
    const m = Number(f.constraints?.maxFiles);
    return !Number.isNaN(m) && m > 0 ? m : 3;
  }
  protected removeFile(f: FbField, name: string): void {
    this.setVal(f, this.arr(f).filter((x) => x !== name));
  }

  // helpers cho template (min/max number)
  protected conMinNum(f: FbField): number {
    const m = f.constraints?.min; return m != null && m !== '' && !Number.isNaN(Number(m)) ? Number(m) : -Infinity;
  }
  protected conMaxNum(f: FbField): number {
    const m = f.constraints?.max; return m != null && m !== '' && !Number.isNaN(Number(m)) ? Number(m) : Infinity;
  }

  /** Giá trị hiển thị ở chế độ CHI TIẾT / readonly. */
  protected displayValue(f: FbField): string {
    const v = this.value()[f.key];
    if (f.type === 'autocode') return this.autoCode(f);
    if (v == null || v === '') return '—';
    if (Array.isArray(v)) return (v as string[]).join(', ') || '—';
    if (v instanceof Date) return f.type === 'time' ? fbFmtHM(v) : fbFmtDMY(v);
    if (typeof v === 'boolean') return v ? this.tr('rOn') : this.tr('rOff');
    if (f.type === 'money') return `${v} ${this.unitVal(f)}`;
    if (f.type === 'percent') return `${v}%`;
    return String(v);
  }
}
