import { Component, ElementRef, OnDestroy, computed, effect, inject, input, signal } from '@angular/core';

/** Trạng thái NGOÀI của mascot (host điều khiển) — mô phỏng Rive State Machine.
 *  hover/pressed tự xử lý nội bộ (host listeners), tương đương input isHovered/isPressed. */
export type VnaiState = 'idle' | 'thinking' | 'success' | 'error';

/** sg-vnai-mascot — mascot VNAI "SỐNG" thuần CSS/JS trên PNG 1 lớp (không cần Rive).
 *  Mô phỏng state machine spec (đổi sang .riv sau: giữ nguyên inputs, chỉ thay engine):
 *  · Idle: chớp mắt NGẪU NHIÊN 3–4s (mí overlay màu màn hình mặt) + thở ≤1px.
 *  · Hover: nghiêng thân theo hướng con trỏ (±3°) + mắt sáng hơn (glow overlay).
 *  · Pressed: scale .96 / 100ms.
 *  · Thinking: 3 hạt sáng bay quanh đầu + ánh mắt đảo trái–phải (glow di chuyển).
 *  · Success: badge Check pop (host tự trả về idle sau ~800ms).
 *  · Error: lắc nhẹ 2px (không bi luỵ) + badge Retry.
 *  Enterprise-safe: biên độ nhỏ; tôn trọng prefers-reduced-motion (tĩnh hoàn toàn);
 *  tự DỪNG khi ra khỏi viewport (IntersectionObserver); PNG gốc chính là fallback tĩnh. */
@Component({
  selector: 'sg-vnai-mascot',
  template: `
    <div class="vm" [class.vm--paused]="paused()" [class.vm--think]="state() === 'thinking'"
      [class.vm--error]="state() === 'error'" [class.vm--success]="state() === 'success'"
      [style.width.px]="size()" [style.--tilt.deg]="tilt()">
      <img class="vm-img" src="/assets/vnai-mascot.png" alt="VNAI" draggable="false" (error)="imgOk.set(false)" />

      @if (imgOk() && motionOn) {
        <!-- Mí mắt (chớp) — màu màn hình mặt robot, đè đúng toạ độ 2 mắt -->
        <span class="vm-lid vm-lid--l" [class.is-blink]="blinking()"></span>
        <span class="vm-lid vm-lid--r" [class.is-blink]="blinking()"></span>
        <!-- Glow mắt: sáng hơn khi hover · đảo trái-phải khi thinking -->
        <span class="vm-glow vm-glow--l"></span>
        <span class="vm-glow vm-glow--r"></span>
        <!-- 3 hạt sáng quanh đầu (thinking) -->
        <span class="vm-dot vm-dot--1"></span>
        <span class="vm-dot vm-dot--2"></span>
        <span class="vm-dot vm-dot--3"></span>
      }

      <!-- Badge kết quả (success/error) -->
      @if (state() === 'success') {
        <span class="vm-badge vm-badge--ok" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12.5 9.5 18 20 6.5" /></svg>
        </span>
      }
      @if (state() === 'error') {
        <span class="vm-badge vm-badge--err" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M20 11a8 8 0 1 0-2.5 6.5" /><path d="M20 5v6h-6" /></svg>
        </span>
      }
    </div>
  `,
  host: {
    '(mouseenter)': 'onEnter()',
    '(mouseleave)': 'onLeave()',
    '(mousemove)': 'onMove($event)',
    '(mousedown)': 'pressed.set(true)',
    '(mouseup)': 'pressed.set(false)',
  },
  styles: [`
    :host { display: inline-block; line-height: 0; }
    .vm { position: relative; transform: rotate(var(--tilt, 0deg)); will-change: transform;
      transition: transform .18s var(--ease-out, ease-out); }
    .vm-img { width: 100%; height: auto; display: block; user-select: none; -webkit-user-drag: none; }

    /* ── Thở: nhún ≤1px, chỉ khi idle (paused/reduced-motion → tắt) ── */
    .vm:not(.vm--paused):not(.vm--error) .vm-img { animation: vm-breath 3.4s ease-in-out infinite; }
    @keyframes vm-breath { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-1px); } }

    /* ── Mí mắt: ellipse màu MÀN HÌNH MẶT robot đè lên mắt; chớp = mở scaleY ── */
    /* Toạ độ mắt ĐO TỪ PIXEL ảnh (canvas scan): trái x 34.3–44% · phải x 58.8–68.3% · y 34.4–43%. */
    .vm-lid { position: absolute; top: 34%; width: 12.5%; height: 10%;
      background: #0F1B3D; border-radius: 46% 46% 50% 50%;
      transform: scaleY(0); transform-origin: center top; pointer-events: none; }
    .vm-lid--l { left: 33.9%; }
    .vm-lid--r { left: 58.4%; }
    .vm-lid.is-blink { animation: vm-blink .15s ease-in; }
    @keyframes vm-blink { 0% { transform: scaleY(0); } 45% { transform: scaleY(1); } 100% { transform: scaleY(0); } }

    /* ── Glow mắt: hover sáng nhẹ · thinking đảo trái-phải ── */
    .vm-glow { position: absolute; top: 35.5%; width: 10.5%; height: 8%; border-radius: 50%;
      background: radial-gradient(circle, rgb(96 165 250 / .95), rgb(96 165 250 / 0) 68%);
      opacity: 0; pointer-events: none; transition: opacity .2s var(--ease-out, ease-out); }
    .vm-glow--l { left: 34.9%; }
    .vm-glow--r { left: 59.4%; }
    :host(:hover) .vm-glow { opacity: .55; }
    .vm--think .vm-glow { opacity: .8; animation: vm-dart 1.5s ease-in-out infinite; }
    @keyframes vm-dart {
      0%, 100% { transform: translateX(-14%); }
      50% { transform: translateX(14%); }
    }

    /* ── 3 hạt sáng quanh đầu (thinking) ── */
    .vm-dot { position: absolute; width: 7%; height: 7%; border-radius: 50%; opacity: 0; pointer-events: none;
      background: radial-gradient(circle, #93C5FD, rgb(147 197 253 / 0) 72%); }
    .vm--think .vm-dot { animation: vm-orbit 1.8s ease-in-out infinite; }
    .vm-dot--1 { left: 6%; top: 12%; }
    .vm-dot--2 { left: 46%; top: -6%; animation-delay: .3s !important; }
    .vm-dot--3 { left: 84%; top: 12%; animation-delay: .6s !important; }
    @keyframes vm-orbit {
      0%, 100% { opacity: 0; transform: translateY(2px) scale(.6); }
      40% { opacity: .95; transform: translateY(-3px) scale(1); }
      70% { opacity: .4; }
    }

    /* ── Error: lắc NHẸ 2px, không bi luỵ ── */
    .vm--error { animation: vm-shake .4s ease-in-out; }
    @keyframes vm-shake {
      0%, 100% { transform: translateX(0) rotate(var(--tilt, 0deg)); }
      25% { transform: translateX(-2px) rotate(var(--tilt, 0deg)); }
      75% { transform: translateX(2px) rotate(var(--tilt, 0deg)); }
    }

    /* ── Success: nhún vui 1 nhịp ── */
    .vm--success { animation: vm-hop .45s var(--ease-out, ease-out); }
    @keyframes vm-hop {
      0%, 100% { transform: translateY(0) rotate(var(--tilt, 0deg)); }
      40% { transform: translateY(-4px) rotate(var(--tilt, 0deg)); }
    }

    /* ── Badge Check / Retry (800ms do host điều khiển state) ── */
    .vm-badge { position: absolute; top: -6%; right: -10%; display: grid; place-items: center;
      width: 38%; height: 38%; border-radius: 50%; color: #fff;
      box-shadow: 0 2px 8px rgb(0 0 0 / .22); animation: vm-pop .3s var(--ease-out, ease-out); }
    .vm-badge svg { width: 62%; height: 62%; }
    .vm-badge--ok { background: var(--success-base, #16A34A); }
    .vm-badge--err { background: var(--warning-base, #F59E0B); }
    @keyframes vm-pop { from { transform: scale(.4); opacity: 0; } to { transform: scale(1); opacity: 1; } }

    /* ── Paused (ngoài viewport) + reduced-motion: tĩnh hoàn toàn, chỉ còn opacity transition ── */
    .vm--paused * { animation-play-state: paused !important; }
    @media (prefers-reduced-motion: reduce) {
      .vm, .vm * { animation: none !important; transition: opacity .2s ease !important; }
    }
  `],
})
export class SgVnaiMascot implements OnDestroy {
  /** Bề rộng mascot (px). */
  readonly size = input(56);
  /** Trạng thái ngoài (idle/thinking/success/error) — host điều khiển. */
  readonly state = input<VnaiState>('idle');

  protected readonly imgOk = signal(true);
  protected readonly blinking = signal(false);
  protected readonly pressed = signal(false);
  protected readonly paused = signal(false);
  /** Nghiêng thân theo hướng con trỏ khi hover (±3° — enterprise-safe). */
  protected readonly tilt = signal(0);

  private readonly el = inject(ElementRef<HTMLElement>);
  /** Reduced-motion → không đặt timer chớp mắt, mọi animation tắt bằng CSS. */
  protected readonly motionOn = typeof matchMedia === 'undefined' || !matchMedia('(prefers-reduced-motion: reduce)').matches;
  private blinkTimer: ReturnType<typeof setTimeout> | null = null;
  private io: IntersectionObserver | null = null;

  constructor() {
    if (this.motionOn) this.scheduleBlink();
    // Dừng toàn bộ khi ra khỏi viewport (spec: stop when out of view).
    try {
      this.io = new IntersectionObserver(([e]) => this.paused.set(!e.isIntersecting));
      this.io.observe(this.el.nativeElement);
    } catch { /* SSR/không hỗ trợ */ }
    // Pressed: scale .96/100ms — áp qua tilt-transform wrapper (transition .18s đã mượt).
    effect(() => {
      const host = this.el.nativeElement as HTMLElement;
      host.style.transform = this.pressed() ? 'scale(.96)' : '';
      host.style.transition = 'transform .1s ease-out';
    });
  }

  /** Chớp mắt ngẫu nhiên 3–4s (thỉnh thoảng chớp đúp) — chỉ khi hiện trong viewport. */
  private scheduleBlink(): void {
    const delay = 3000 + Math.random() * 1000;
    this.blinkTimer = setTimeout(() => {
      if (!this.paused()) {
        this.blink();
        if (Math.random() < 0.25) setTimeout(() => this.blink(), 260); // chớp đúp 25%
      }
      this.scheduleBlink();
    }, delay);
  }
  private blink(): void {
    this.blinking.set(true);
    setTimeout(() => this.blinking.set(false), 170);
  }

  protected onEnter(): void { /* glow qua :host(:hover) CSS */ }
  protected onLeave(): void { this.tilt.set(0); this.pressed.set(false); }
  /** pointerX → nghiêng thân về phía con trỏ (mô phỏng "nhìn theo"). */
  protected onMove(e: MouseEvent): void {
    if (!this.motionOn) return;
    const r = this.el.nativeElement.getBoundingClientRect();
    const rel = (e.clientX - r.left) / r.width - 0.5; // -0.5..0.5
    this.tilt.set(Math.round(rel * 6 * 10) / 10);     // ±3°
  }

  ngOnDestroy(): void {
    if (this.blinkTimer) clearTimeout(this.blinkTimer);
    this.io?.disconnect();
  }
}
